const state = $getWorkflowStaticData('global');
if (!state.issues) state.issues = {};
if (!state.lqa) state.lqa = {};
if (!state.versions) state.versions = {};
if (!state.naPinged) state.naPinged = {};
const firstRun = !state.seeded;
const lqaFirstRun = !state.lqaSeeded;
const naFirstRun = !state.naSeeded;
const now = Date.now();
const LINK_TYPE_ID = '10079'; // "Has localization ticket"
const LQA_LEAD = 'U09H1QEDX9C'; // Kseniya Krasovskaya, LQA lead pinged for LQA/LLR status problems
const SUB = '      ◦ '; // indented sub-bullet for version lists
const ARROW = ' → '; // used for every status, current or changed
const esc = function (s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const base = 'https://futuremedia.atlassian.net/browse/';
const link = function (k) { return '<' + base + k + '|' + k + '>'; };
const sigOf = function (v) { return v.name + '|' + v.releaseDate + '|' + v.released; };
const parseSig = function (s) { const parts = s.split('|'); const released = parts.pop() === 'true'; const releaseDate = parts.pop() || ''; return { name: parts.join('|'), releaseDate: releaseDate, released: released }; };
const verLineOf = function (versions) { if (!versions) return 'unknown'; return versions.length ? versions.map(function (v) { return esc(v.name) + ' (' + (v.releaseDate || 'no date') + (v.released ? ', released' : ', not released') + ')'; }).join(', ') : 'none'; };
// Thread of the latest version message (#i18n-releases) for any of the ticket's fix versions
const versionThreadOf = function (ids) { let ts = ''; (ids || []).forEach(function (id) { const vs = state.versions[id]; if (vs && vs.threadTs) ts = vs.threadTs; }); return ts; };
// Head of a ticket post: header, changes, then the LLR (linked localization request) status.
// LQA lines (only when available) and the fix version are appended in "Add LQA line".
const buildText = function (key, summary, changes, llrText) {
  return ':bell: *' + link(key) + '* – ' + esc(summary) + '\n' + changes.join('\n') + '\n' + llrText;
};
const llrStatusText = function (pairs) {
  return pairs.map(function (p) { return 'LLR: ' + link(p.key) + ARROW + '*' + esc(p.status || 'unknown') + '*'; }).join('\n');
};

const productIssues = (($('Fetch localized product tickets').first().json || {}).issues) || [];
let llrIssues = [];
try { llrIssues = ($input.first().json.issues) || []; } catch (e) { llrIssues = []; }
const llrByKey = {};
for (const l of llrIssues) llrByKey[l.key] = l;

// 1) LQA status changes on LLRs (INTERNAT), and LLRs Done without an LQA status
const lqaChanges = {}; // product key -> { lines, llrKeys, issue, hasNa }
const addLine = function (p, llKey, line, isNa) {
  if (!lqaChanges[p.key]) lqaChanges[p.key] = { lines: [], llrKeys: [], issue: p, hasNa: false };
  lqaChanges[p.key].lines.push(line);
  if (isNa) lqaChanges[p.key].hasNa = true;
  if (lqaChanges[p.key].llrKeys.indexOf(llKey) < 0) lqaChanges[p.key].llrKeys.push(llKey);
};
for (const l of llrIssues) {
  const f = l.fields || {};
  const val = f.customfield_11581 ? f.customfield_11581.value : '';
  const prev = state.lqa[l.key];
  state.lqa[l.key] = { value: val, seen: now };
  const products = (f.issuelinks || []).filter(function (x) { return x.type && x.type.id === LINK_TYPE_ID && x.inwardIssue; }).map(function (x) { return x.inwardIssue; });

  // LLR is Done but LQA status is NA / not set -> ping the LQA lead once per LLR
  const llStatus = f.status ? String(f.status.name || '') : '';
  const lqaMissing = !val || /^n\s*\/?\s*a$/i.test(String(val).trim());
  if (/^done$/i.test(llStatus.trim()) && lqaMissing) {
    if (!state.naPinged[l.key]) {
      state.naPinged[l.key] = { seen: now };
      // First run only records tickets that were already in this state
      if (!naFirstRun) {
        for (const p of products) addLine(p, l.key, ':rotating_light: <@' + LQA_LEAD + '> ' + link(l.key) + ' is *Done* but its LQA status is *' + esc(val || 'not set') + '*. All linked localization requests need a selected LQA status.', true);
      }
    } else {
      state.naPinged[l.key].seen = now;
    }
  } else {
    delete state.naPinged[l.key];
  }

  if (lqaFirstRun) continue;
  // An LLR seen for the first time is only recorded, never reported
  if (!(prev && prev.value !== val)) continue;
  const fromTxt = prev.value || 'not set';
  for (const p of products) addLine(p, l.key, ':mag: LQA status (' + link(l.key) + '): ' + esc(fromTxt) + ARROW + '*' + esc(val || 'not set') + '*', false);
}

const out = [];
const groups = {}; // version-level events, one message per version + event
const groupOrder = [];
// 2) Product tickets: ticket-level changes go per ticket, version-level events are grouped per version
for (const it of productIssues) {
  const f = it.fields || {};
  const llrs = (f.issuelinks || []).filter(function (l) { return l.type && l.type.id === LINK_TYPE_ID && l.outwardIssue; }).map(function (l) { return l.outwardIssue; });
  if (!llrs.length) continue;
  const status = f.status ? f.status.name : '';
  const versions = (f.fixVersions || []).map(function (v) { return { id: v.id, name: v.name, releaseDate: v.releaseDate || '', released: !!v.released }; });
  const verSig = versions.map(sigOf).sort().join(';');
  const prev = state.issues[it.key];
  state.issues[it.key] = { status: status, verSig: verSig, verIds: versions.map(function (v) { return String(v.id || v.name); }), seen: now, threadTs: prev && prev.threadTs ? prev.threadTs : '', summary: f.summary || '', llrKeys: llrs.map(function (l) { return l.key; }) };
  const lqa = lqaChanges[it.key];
  delete lqaChanges[it.key];
  // Version list sub-bullets: one "LLR" line per LLR, then its LQA status when set
  const llrBlock = llrs.map(function (l) {
    const st = l.fields && l.fields.status ? l.fields.status.name : '';
    const li = llrByKey[l.key];
    const q = li && li.fields && li.fields.customfield_11581 ? li.fields.customfield_11581.value : '';
    return SUB + 'LLR: ' + link(l.key) + (st ? ARROW + '*' + esc(st) + '*' : '') + (q ? '\n' + SUB + 'LQA status' + ARROW + '*' + esc(q) + '*' : '');
  }).join('\n');
  const llrText = llrStatusText(llrs.map(function (l) { return { key: l.key, status: l.fields && l.fields.status ? l.fields.status.name : '' }; }));
  const changes = [];
  if (!firstRun && prev) {
    if (prev.status !== null && prev.status !== undefined && prev.status !== status) {
      const prodNote = status === 'QA PROD' ? ' :rocket: _deployed to prod_' : '';
      changes.push('Main ticket status: ' + esc(prev.status) + ARROW + '*' + esc(status) + '*' + prodNote);
      // Main ticket just moved to Done while its LLR is still in DEV Verification -> ping the LQA lead
      if (/^done$/i.test(status.trim())) {
        const stuck = llrs.filter(function (l) { const s = l.fields && l.fields.status ? l.fields.status.name : ''; return /dev verification/i.test(s); });
        if (stuck.length) changes.push(':rotating_light: <@' + LQA_LEAD + '> main ticket is *Done* but ' + stuck.map(function (l) { return link(l.key); }).join(', ') + (stuck.length > 1 ? ' are' : ' is') + ' still in *DEV Verification*');
      }
    }
    if (prev.verSig !== null && prev.verSig !== undefined && prev.verSig !== verSig) {
      const prevVers = prev.verSig ? prev.verSig.split(';').map(parseSig) : [];
      for (const v of versions) {
        const p = prevVers.find(function (x) { return x.name === v.name; });
        let event = '';
        if (!p) changes.push('Fix version added: *' + esc(v.name) + '*' + (v.releaseDate ? ' (planned release ' + v.releaseDate + ')' : ''));
        else if (v.released && !p.released) event = ':rocket: *released*' + (v.releaseDate ? ' on *' + v.releaseDate + '*' : '');
        else if (!v.released && p.released) event = ':warning: release *reverted* (marked as not released again)';
        else if (p.releaseDate !== v.releaseDate) event = ':calendar: release date moved: ' + (p.releaseDate || 'not set') + ARROW + '*' + (v.releaseDate || 'not set') + '*';
        if (event) {
          const gk = (v.id || v.name) + '#' + event;
          if (!groups[gk]) { groups[gk] = { versionId: v.id || v.name, version: v, project: it.key.split('-')[0], event: event, tickets: [], keys: [], llrKeys: [] }; groupOrder.push(gk); }
          groups[gk].tickets.push('• ' + link(it.key) + ' – ' + esc(f.summary) + ARROW + '*' + esc(status) + '*\n' + llrBlock);
          if (groups[gk].keys.indexOf(it.key) < 0) groups[gk].keys.push(it.key);
          for (const l of llrs) if (groups[gk].llrKeys.indexOf(l.key) < 0) groups[gk].llrKeys.push(l.key);
        }
      }
      for (const p of prevVers) {
        if (!versions.find(function (v) { return v.name === p.name; })) changes.push('Fix version removed: *' + esc(p.name) + '*');
      }
    }
  }
  if (lqa) for (const line of lqa.lines) changes.push(line);
  if (!changes.length) continue;
  // LQA-only updates: reply in the version thread if the ticket was listed in one, else the ticket's own thread.
  // Plain LQA updates are never posted as a new message (Kseniya pings still are).
  let threadTs = state.issues[it.key].threadTs;
  let changesText = changes.join('\n') + '\n' + llrText;
  if (lqa && changes.length === lqa.lines.length) {
    const vt = versionThreadOf(state.issues[it.key].verIds);
    if (vt) { threadTs = vt; changesText = '• ' + link(it.key) + ' – ' + esc(f.summary) + ARROW + '*' + esc(status) + '*\n' + changesText; }
    if (!threadTs && !lqa.hasNa) continue;
  }
  out.push({ json: { kind: 'ticket', groupKey: '', key: it.key, status: status, llrKeys: llrs.map(function (l) { return l.key; }), threadTs: threadTs, changesText: changesText, text: buildText(it.key, f.summary, changes, llrText), tail: 'Fix version: ' + verLineOf(versions) } });
}

// 3) One message per version event, listing every localized ticket in that version.
// A version with a single localized ticket that already has its own thread is posted inside that thread instead,
// and that thread becomes the version's thread for later events.
for (const gk of groupOrder) {
  const g = groups[gk];
  const v = g.version;
  const vs = state.versions[g.versionId] || { threadTs: '' };
  vs.seen = now;
  if (!vs.threadTs && g.keys.length === 1) {
    const ti = state.issues[g.keys[0]];
    if (ti && ti.threadTs) vs.threadTs = ti.threadTs;
  }
  state.versions[g.versionId] = vs;
  const header = ':package: *Version ' + esc(v.name) + '* (' + esc(g.project) + ') – ' + g.event;
  const body = 'Release: ' + (v.releaseDate || 'no date') + (v.released ? ', released' : ', not released') + '\n' + g.tickets.join('\n');
  out.push({ json: { kind: 'version', groupKey: String(g.versionId), key: 'Version ' + v.name, status: '', llrKeys: g.llrKeys, threadTs: vs.threadTs || '', changesText: header + '\n' + body, text: header + '\n' + body, tail: '' } });
}

// 4) LQA lines whose product ticket was not in this run's product fetch
for (const key of Object.keys(lqaChanges)) {
  const c = lqaChanges[key];
  const pf = c.issue.fields || {};
  let st = state.issues[key];
  if (!st) {
    st = { status: null, verSig: null, verIds: [], seen: now, threadTs: '', summary: pf.summary || '', llrKeys: c.llrKeys };
    state.issues[key] = st;
  }
  const llrKeys = st.llrKeys && st.llrKeys.length ? st.llrKeys : c.llrKeys;
  const versions = st.verSig ? st.verSig.split(';').map(parseSig) : (st.verSig === '' ? [] : null);
  const llrText = llrStatusText(llrKeys.map(function (k) { const li = llrByKey[k]; return { key: k, status: li && li.fields && li.fields.status ? li.fields.status.name : '' }; }));
  const mainStatus = pf.status ? pf.status.name : (st.status || '');
  let threadTs = st.threadTs || '';
  let changesText = c.lines.join('\n') + '\n' + llrText;
  const vt = versionThreadOf(st.verIds);
  if (vt) { threadTs = vt; changesText = '• ' + link(key) + ' – ' + esc(pf.summary || st.summary) + (mainStatus ? ARROW + '*' + esc(mainStatus) + '*' : '') + '\n' + changesText; }
  if (!threadTs && !c.hasNa) continue; // plain LQA updates only go into an existing thread
  out.push({ json: { kind: 'ticket', groupKey: '', key: key, status: mainStatus, llrKeys: llrKeys, threadTs: threadTs, changesText: changesText, text: buildText(key, pf.summary || st.summary, c.lines, llrText), tail: 'Fix version: ' + verLineOf(versions) } });
}

const old = function (o) { return now - ((o && o.seen) || 0) > 90 * 86400000; };
for (const k of Object.keys(state.issues)) if (old(state.issues[k])) delete state.issues[k];
for (const k of Object.keys(state.lqa)) if (old(state.lqa[k])) delete state.lqa[k];
for (const k of Object.keys(state.versions)) if (old(state.versions[k])) delete state.versions[k];
for (const k of Object.keys(state.naPinged)) if (old(state.naPinged[k])) delete state.naPinged[k];
state.seeded = true;
state.lqaSeeded = true;
state.naSeeded = true;
return out;

const state = $getWorkflowStaticData('global');
const src = $('Add LQA line').item.json;
const ts = $json.message_timestamp || ($json.message && $json.message.ts);
if (ts) {
  if (src.kind === 'version') {
    if (!state.versions) state.versions = {};
    const v = state.versions[src.groupKey] || {};
    v.threadTs = ts;
    v.seen = Date.now();
    state.versions[src.groupKey] = v;
  } else if (src.key && state.issues && state.issues[src.key]) {
    state.issues[src.key].threadTs = ts;
  }
}
return { json: { key: src.key, threadTs: ts } };

// On each LLR: "Original fix version" / "Original release date" are filled only when empty (first plan, never overwritten).
// "Target end" always follows the main ticket's current release date, overwriting manual edits. Done LLRs are left alone.
const LINK_TYPE_ID = '10079';
const productIssues = (($('Fetch localized product tickets').first().json || {}).issues) || [];
let llrIssues = [];
try { llrIssues = ($input.first().json.issues) || []; } catch (e) { llrIssues = []; }
const llrByKey = {};
for (const l of llrIssues) llrByKey[l.key] = l;
const updates = {};
for (const it of productIssues) {
  const f = it.fields || {};
  const dated = (f.fixVersions || []).filter(function (v) { return v.name && v.releaseDate; });
  if (!dated.length) continue;
  // If several versions are set, use the earliest unreleased one, else the earliest one
  dated.sort(function (a, b) { return (a.released === b.released ? 0 : (a.released ? 1 : -1)) || a.releaseDate.localeCompare(b.releaseDate); });
  const v = dated[0];
  const llrs = (f.issuelinks || []).filter(function (l) { return l.type && l.type.id === LINK_TYPE_ID && l.outwardIssue; }).map(function (l) { return l.outwardIssue.key; });
  for (const k of llrs) {
    const li = llrByKey[k];
    if (!li || updates[k]) continue;
    const lf = li.fields || {};
    const done = !!(lf.status && lf.status.statusCategory && lf.status.statusCategory.key === 'done');
    const fields = {};
    if (!lf.customfield_11702) fields.customfield_11702 = v.name;
    if (!lf.customfield_11703) fields.customfield_11703 = v.releaseDate;
    if (!done && String(lf.customfield_10023 || '').slice(0, 10) !== v.releaseDate) fields.customfield_10023 = v.releaseDate;
    if (Object.keys(fields).length) updates[k] = { key: k, productKey: it.key, fields: fields };
  }
}
return Object.keys(updates).map(function (k) { return { json: updates[k] }; });

// Product tickets with an LLR: updated recently, in an unreleased version, recently released,
// plus every ticket last seen in an unreleased version (releasing a version or moving its date does not update the ticket)
const state = $getWorkflowStaticData('global');
const issues = state.issues || {};
const tracked = Object.keys(issues).filter(function (k) { const s = issues[k]; return s && s.verSig && s.verSig.split(';').some(function (x) { return x.slice(-6) === '|false'; }); }).slice(0, 150);
const jql = 'issueLinkType = "Has localization ticket" AND project != INTERNAT AND (updated >= -3d OR fixVersion in unreleasedVersions() OR (fixVersion in releasedVersions() AND updated >= -14d)' + (tracked.length ? ' OR key in (' + tracked.join(',') + ')' : '') + ') ORDER BY updated DESC';
return [{ json: { jql: jql, tracked: tracked.length } }];

// One alert per version released in this run, only when it contains product tickets whose LLR is not Done.
// Only the LLRs that are not Done are listed.
const LINK_TYPE_ID = '10079';
const base = 'https://futuremedia.atlassian.net/browse/';
const link = function (k) { return '<' + base + k + '|' + k + '>'; };
const esc = function (s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const products = (($('Fetch localized product tickets').first().json || {}).issues) || [];
const out = [];
for (const item of $input.all()) {
  const d = item.json || {};
  if (d.kind !== 'version' || String(d.text || '').indexOf(':rocket: *released*') < 0) continue;
  let vName = '', vDate = '', project = '', open = 0;
  const lines = [];
  for (const it of products) {
    const f = it.fields || {};
    const v = (f.fixVersions || []).find(function (x) { return String(x.id || x.name) === String(d.groupKey); });
    if (!v) continue;
    const openLlrs = (f.issuelinks || []).filter(function (l) { return l.type && l.type.id === LINK_TYPE_ID && l.outwardIssue; }).map(function (l) { return l.outwardIssue; }).filter(function (l) { const st = l.fields && l.fields.status; return !(st && st.statusCategory && st.statusCategory.key === 'done'); });
    if (!openLlrs.length) continue;
    vName = v.name; vDate = v.releaseDate || vDate; project = it.key.split('-')[0];
    open += openLlrs.length;
    const sub = openLlrs.map(function (l) { const st = l.fields && l.fields.status; return '      ◦ LLR: ' + link(l.key) + ' → *' + esc(st ? st.name : 'unknown') + '*'; });
    lines.push('• ' + link(it.key) + ' – ' + esc(f.summary) + ' → *' + esc(f.status ? f.status.name : '') + '*\n' + sub.join('\n'));
  }
  if (!open) continue;
  const head = ':rotating_light: *Released with open localization work* – Version *' + esc(vName) + '* (' + esc(project) + ')' + (vDate ? ', released on *' + vDate + '*' : '');
  const sum = '*' + open + ' linked localization request' + (open > 1 ? 's are' : ' is') + ' not Done yet.*';
  out.push({ json: { text: head + '\n' + sum + '\n' + lines.join('\n') } });
}
return out;

const state = $getWorkflowStaticData('global');
if (!state.issues) state.issues = {};
if (!state.lqa) state.lqa = {};
if (!state.versions) state.versions = {};
if (!state.naPinged) state.naPinged = {};
const firstRun = !state.seeded;
const lqaFirstRun = !state.lqaSeeded;
const naFirstRun = !state.naSeeded;
const now = Date.now();
const LINK_TYPE_ID = '10079'; // "Has localization ticket"
const LQA_LEAD = 'U09H1QEDX9C'; // Kseniya Krasovskaya, LQA lead pinged for LQA/LLR status problems
const SUB = '      ◦ '; // indented sub-bullet for version lists
const ARROW = ' → '; // used for every status, current or changed
const esc = function (s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const base = 'https://futuremedia.atlassian.net/browse/';
const link = function (k) { return '<' + base + k + '|' + k + '>'; };
const sigOf = function (v) { return v.name + '|' + v.releaseDate + '|' + v.released; };
const parseSig = function (s) { const parts = s.split('|'); const released = parts.pop() === 'true'; const releaseDate = parts.pop() || ''; return { name: parts.join('|'), releaseDate: releaseDate, released: released }; };
const verLineOf = function (versions) { if (!versions) return 'unknown'; return versions.length ? versions.map(function (v) { return esc(v.name) + ' (' + (v.releaseDate || 'no date') + (v.released ? ', released' : ', not released') + ')'; }).join(', ') : 'none'; };
// Thread of the latest version message (#i18n-releases) for any of the ticket's fix versions
const versionThreadOf = function (ids) { let ts = ''; (ids || []).forEach(function (id) { const vs = state.versions[id]; if (vs && vs.threadTs) ts = vs.threadTs; }); return ts; };
// Head of a ticket post: header, changes, then the LLR (linked localization request) status.
// LQA lines (only when available) and the fix version are appended in "Add LQA line".
const buildText = function (key, summary, changes, llrText) {
  return ':bell: *' + link(key) + '* – ' + esc(summary) + '\n' + changes.join('\n') + '\n' + llrText;
};
const llrStatusText = function (pairs) {
  return pairs.map(function (p) { return 'LLR: ' + link(p.key) + ARROW + '*' + esc(p.status || 'unknown') + '*'; }).join('\n');
};

const productIssues = (($('Fetch localized product tickets').first().json || {}).issues) || [];
let llrIssues = [];
try { llrIssues = ($input.first().json.issues) || []; } catch (e) { llrIssues = []; }
const llrByKey = {};
for (const l of llrIssues) llrByKey[l.key] = l;

// 1) LQA status changes on LLRs (INTERNAT), and LLRs Done without an LQA status
const lqaChanges = {}; // product key -> { lines, llrKeys, issue, hasNa }
const addLine = function (p, llKey, line, isNa) {
  if (!lqaChanges[p.key]) lqaChanges[p.key] = { lines: [], llrKeys: [], issue: p, hasNa: false };
  lqaChanges[p.key].lines.push(line);
  if (isNa) lqaChanges[p.key].hasNa = true;
  if (lqaChanges[p.key].llrKeys.indexOf(llKey) < 0) lqaChanges[p.key].llrKeys.push(llKey);
};
for (const l of llrIssues) {
  const f = l.fields || {};
  const val = f.customfield_11581 ? f.customfield_11581.value : '';
  const prev = state.lqa[l.key];
  state.lqa[l.key] = { value: val, seen: now };
  const products = (f.issuelinks || []).filter(function (x) { return x.type && x.type.id === LINK_TYPE_ID && x.inwardIssue; }).map(function (x) { return x.inwardIssue; });

  // LLR is Done but LQA status is NA / not set -> ping the LQA lead once per LLR
  const llStatus = f.status ? String(f.status.name || '') : '';
  const lqaMissing = !val || /^n\s*\/?\s*a$/i.test(String(val).trim());
  if (/^done$/i.test(llStatus.trim()) && lqaMissing) {
    if (!state.naPinged[l.key]) {
      state.naPinged[l.key] = { seen: now };
      // First run only records tickets that were already in this state
      if (!naFirstRun) {
        for (const p of products) addLine(p, l.key, ':rotating_light: <@' + LQA_LEAD + '> ' + link(l.key) + ' is *Done* but its LQA status is *' + esc(val || 'not set') + '*. All linked localization requests need a selected LQA status.', true);
      }
    } else {
      state.naPinged[l.key].seen = now;
    }
  } else {
    delete state.naPinged[l.key];
  }

  if (lqaFirstRun) continue;
  // An LLR seen for the first time is only recorded, never reported
  if (!(prev && prev.value !== val)) continue;
  const fromTxt = prev.value || 'not set';
  for (const p of products) addLine(p, l.key, ':mag: LQA status (' + link(l.key) + '): ' + esc(fromTxt) + ARROW + '*' + esc(val || 'not set') + '*', false);
}

const out = [];
const groups = {}; // version-level events, one message per version + event
const groupOrder = [];
// 2) Product tickets: ticket-level changes go per ticket, version-level events are grouped per version
for (const it of productIssues) {
  const f = it.fields || {};
  const llrs = (f.issuelinks || []).filter(function (l) { return l.type && l.type.id === LINK_TYPE_ID && l.outwardIssue; }).map(function (l) { return l.outwardIssue; });
  if (!llrs.length) continue;
  const status = f.status ? f.status.name : '';
  const versions = (f.fixVersions || []).map(function (v) { return { id: v.id, name: v.name, releaseDate: v.releaseDate || '', released: !!v.released }; });
  const verSig = versions.map(sigOf).sort().join(';');
  const prev = state.issues[it.key];
  state.issues[it.key] = { status: status, verSig: verSig, verIds: versions.map(function (v) { return String(v.id || v.name); }), seen: now, threadTs: prev && prev.threadTs ? prev.threadTs : '', summary: f.summary || '', llrKeys: llrs.map(function (l) { return l.key; }) };
  const lqa = lqaChanges[it.key];
  delete lqaChanges[it.key];
  // Version list sub-bullets: one "LLR" line per LLR, then its LQA status when set
  const llrBlock = llrs.map(function (l) {
    const st = l.fields && l.fields.status ? l.fields.status.name : '';
    const li = llrByKey[l.key];
    const q = li && li.fields && li.fields.customfield_11581 ? li.fields.customfield_11581.value : '';
    return SUB + 'LLR: ' + link(l.key) + (st ? ARROW + '*' + esc(st) + '*' : '') + (q ? '\n' + SUB + 'LQA status' + ARROW + '*' + esc(q) + '*' : '');
  }).join('\n');
  const llrText = llrStatusText(llrs.map(function (l) { return { key: l.key, status: l.fields && l.fields.status ? l.fields.status.name : '' }; }));
  const changes = [];
  if (!firstRun && prev) {
    if (prev.status !== null && prev.status !== undefined && prev.status !== status) {
      const prodNote = status === 'QA PROD' ? ' :rocket: _deployed to prod_' : '';
      changes.push('Main ticket status: ' + esc(prev.status) + ARROW + '*' + esc(status) + '*' + prodNote);
      // Main ticket just moved to Done while its LLR is still in DEV Verification -> ping the LQA lead
      if (/^done$/i.test(status.trim())) {
        const stuck = llrs.filter(function (l) { const s = l.fields && l.fields.status ? l.fields.status.name : ''; return /dev verification/i.test(s); });
        if (stuck.length) changes.push(':rotating_light: <@' + LQA_LEAD + '> main ticket is *Done* but ' + stuck.map(function (l) { return link(l.key); }).join(', ') + (stuck.length > 1 ? ' are' : ' is') + ' still in *DEV Verification*');
      }
    }
    if (prev.verSig !== null && prev.verSig !== undefined && prev.verSig !== verSig) {
      const prevVers = prev.verSig ? prev.verSig.split(';').map(parseSig) : [];
      for (const v of versions) {
        const p = prevVers.find(function (x) { return x.name === v.name; });
        let event = '';
        if (!p) changes.push('Fix version added: *' + esc(v.name) + '*' + (v.releaseDate ? ' (planned release ' + v.releaseDate + ')' : ''));
        else if (v.released && !p.released) event = ':rocket: *released*' + (v.releaseDate ? ' on *' + v.releaseDate + '*' : '');
        else if (!v.released && p.released) event = ':warning: release *reverted* (marked as not released again)';
        else if (p.releaseDate !== v.releaseDate) event = ':calendar: release date moved: ' + (p.releaseDate || 'not set') + ARROW + '*' + (v.releaseDate || 'not set') + '*';
        if (event) {
          const gk = (v.id || v.name) + '#' + event;
          if (!groups[gk]) { groups[gk] = { versionId: v.id || v.name, version: v, project: it.key.split('-')[0], event: event, tickets: [], keys: [], llrKeys: [] }; groupOrder.push(gk); }
          groups[gk].tickets.push('• ' + link(it.key) + ' – ' + esc(f.summary) + ARROW + '*' + esc(status) + '*\n' + llrBlock);
          if (groups[gk].keys.indexOf(it.key) < 0) groups[gk].keys.push(it.key);
          for (const l of llrs) if (groups[gk].llrKeys.indexOf(l.key) < 0) groups[gk].llrKeys.push(l.key);
        }
      }
      for (const p of prevVers) {
        if (!versions.find(function (v) { return v.name === p.name; })) changes.push('Fix version removed: *' + esc(p.name) + '*');
      }
    }
  }
  if (lqa) for (const line of lqa.lines) changes.push(line);
  if (!changes.length) continue;
  // LQA-only updates: reply in the version thread if the ticket was listed in one, else the ticket's own thread.
  // Plain LQA updates are never posted as a new message (Kseniya pings still are).
  let threadTs = state.issues[it.key].threadTs;
  let changesText = changes.join('\n') + '\n' + llrText;
  if (lqa && changes.length === lqa.lines.length) {
    const vt = versionThreadOf(state.issues[it.key].verIds);
    if (vt) { threadTs = vt; changesText = '• ' + link(it.key) + ' – ' + esc(f.summary) + ARROW + '*' + esc(status) + '*\n' + changesText; }
    if (!threadTs && !lqa.hasNa) continue;
  }
  out.push({ json: { kind: 'ticket', groupKey: '', key: it.key, status: status, llrKeys: llrs.map(function (l) { return l.key; }), threadTs: threadTs, changesText: changesText, text: buildText(it.key, f.summary, changes, llrText), tail: 'Fix version: ' + verLineOf(versions) } });
}

// 3) One message per version event, listing every localized ticket in that version.
// A version with a single localized ticket that already has its own thread is posted inside that thread instead,
// and that thread becomes the version's thread for later events.
for (const gk of groupOrder) {
  const g = groups[gk];
  const v = g.version;
  const vs = state.versions[g.versionId] || { threadTs: '' };
  vs.seen = now;
  if (!vs.threadTs && g.keys.length === 1) {
    const ti = state.issues[g.keys[0]];
    if (ti && ti.threadTs) vs.threadTs = ti.threadTs;
  }
  state.versions[g.versionId] = vs;
  const header = ':package: *Version ' + esc(v.name) + '* (' + esc(g.project) + ') – ' + g.event;
  const body = 'Release: ' + (v.releaseDate || 'no date') + (v.released ? ', released' : ', not released') + '\n' + g.tickets.join('\n');
  out.push({ json: { kind: 'version', groupKey: String(g.versionId), key: 'Version ' + v.name, status: '', llrKeys: g.llrKeys, threadTs: vs.threadTs || '', changesText: header + '\n' + body, text: header + '\n' + body, tail: '' } });
}

// 4) LQA lines whose product ticket was not in this run's product fetch
for (const key of Object.keys(lqaChanges)) {
  const c = lqaChanges[key];
  const pf = c.issue.fields || {};
  let st = state.issues[key];
  if (!st) {
    st = { status: null, verSig: null, verIds: [], seen: now, threadTs: '', summary: pf.summary || '', llrKeys: c.llrKeys };
    state.issues[key] = st;
  }
  const llrKeys = st.llrKeys && st.llrKeys.length ? st.llrKeys : c.llrKeys;
  const versions = st.verSig ? st.verSig.split(';').map(parseSig) : (st.verSig === '' ? [] : null);
  const llrText = llrStatusText(llrKeys.map(function (k) { const li = llrByKey[k]; return { key: k, status: li && li.fields && li.fields.status ? li.fields.status.name : '' }; }));
  const mainStatus = pf.status ? pf.status.name : (st.status || '');
  let threadTs = st.threadTs || '';
  let changesText = c.lines.join('\n') + '\n' + llrText;
  const vt = versionThreadOf(st.verIds);
  if (vt) { threadTs = vt; changesText = '• ' + link(key) + ' – ' + esc(pf.summary || st.summary) + (mainStatus ? ARROW + '*' + esc(mainStatus) + '*' : '') + '\n' + changesText; }
  if (!threadTs && !c.hasNa) continue; // plain LQA updates only go into an existing thread
  out.push({ json: { kind: 'ticket', groupKey: '', key: key, status: mainStatus, llrKeys: llrKeys, threadTs: threadTs, changesText: changesText, text: buildText(key, pf.summary || st.summary, c.lines, llrText), tail: 'Fix version: ' + verLineOf(versions) } });
}

const old = function (o) { return now - ((o && o.seen) || 0) > 90 * 86400000; };
for (const k of Object.keys(state.issues)) if (old(state.issues[k])) delete state.issues[k];
for (const k of Object.keys(state.lqa)) if (old(state.lqa[k])) delete state.lqa[k];
for (const k of Object.keys(state.versions)) if (old(state.versions[k])) delete state.versions[k];
for (const k of Object.keys(state.naPinged)) if (old(state.naPinged[k])) delete state.naPinged[k];
state.seeded = true;
state.lqaSeeded = true;
state.naSeeded = true;
return out;

const state = $getWorkflowStaticData('global');
const src = $('Add LQA line').item.json;
const ts = $json.message_timestamp || ($json.message && $json.message.ts);
if (ts) {
  if (src.kind === 'version') {
    if (!state.versions) state.versions = {};
    const v = state.versions[src.groupKey] || {};
    v.threadTs = ts;
    v.seen = Date.now();
    state.versions[src.groupKey] = v;
  } else if (src.key && state.issues && state.issues[src.key]) {
    state.issues[src.key].threadTs = ts;
  }
}
return { json: { key: src.key, threadTs: ts } };

// On each LLR: "Original fix version" / "Original release date" are filled only when empty (first plan, never overwritten).
// "Target end" always follows the main ticket's current release date, overwriting manual edits. Done LLRs are left alone.
const LINK_TYPE_ID = '10079';
const productIssues = (($('Fetch localized product tickets').first().json || {}).issues) || [];
let llrIssues = [];
try { llrIssues = ($input.first().json.issues) || []; } catch (e) { llrIssues = []; }
const llrByKey = {};
for (const l of llrIssues) llrByKey[l.key] = l;
const updates = {};
for (const it of productIssues) {
  const f = it.fields || {};
  const dated = (f.fixVersions || []).filter(function (v) { return v.name && v.releaseDate; });
  if (!dated.length) continue;
  // If several versions are set, use the earliest unreleased one, else the earliest one
  dated.sort(function (a, b) { return (a.released === b.released ? 0 : (a.released ? 1 : -1)) || a.releaseDate.localeCompare(b.releaseDate); });
  const v = dated[0];
  const llrs = (f.issuelinks || []).filter(function (l) { return l.type && l.type.id === LINK_TYPE_ID && l.outwardIssue; }).map(function (l) { return l.outwardIssue.key; });
  for (const k of llrs) {
    const li = llrByKey[k];
    if (!li || updates[k]) continue;
    const lf = li.fields || {};
    const done = !!(lf.status && lf.status.statusCategory && lf.status.statusCategory.key === 'done');
    const fields = {};
    if (!lf.customfield_11702) fields.customfield_11702 = v.name;
    if (!lf.customfield_11703) fields.customfield_11703 = v.releaseDate;
    if (!done && String(lf.customfield_10023 || '').slice(0, 10) !== v.releaseDate) fields.customfield_10023 = v.releaseDate;
    if (Object.keys(fields).length) updates[k] = { key: k, productKey: it.key, fields: fields };
  }
}
return Object.keys(updates).map(function (k) { return { json: updates[k] }; });

// Product tickets with an LLR: updated recently, in an unreleased version, recently released,
// plus every ticket last seen in an unreleased version (releasing a version or moving its date does not update the ticket)
const state = $getWorkflowStaticData('global');
const issues = state.issues || {};
const tracked = Object.keys(issues).filter(function (k) { const s = issues[k]; return s && s.verSig && s.verSig.split(';').some(function (x) { return x.slice(-6) === '|false'; }); }).slice(0, 150);
const jql = 'issueLinkType = "Has localization ticket" AND project != INTERNAT AND (updated >= -3d OR fixVersion in unreleasedVersions() OR (fixVersion in releasedVersions() AND updated >= -14d)' + (tracked.length ? ' OR key in (' + tracked.join(',') + ')' : '') + ') ORDER BY updated DESC';
return [{ json: { jql: jql, tracked: tracked.length } }];

// One alert per version released in this run, only when it contains product tickets whose LLR is not Done.
// Only the LLRs that are not Done are listed.
const LINK_TYPE_ID = '10079';
const base = 'https://futuremedia.atlassian.net/browse/';
const link = function (k) { return '<' + base + k + '|' + k + '>'; };
const esc = function (s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const products = (($('Fetch localized product tickets').first().json || {}).issues) || [];
const out = [];
for (const item of $input.all()) {
  const d = item.json || {};
  if (d.kind !== 'version' || String(d.text || '').indexOf(':rocket: *released*') < 0) continue;
  let vName = '', vDate = '', project = '', open = 0;
  const lines = [];
  for (const it of products) {
    const f = it.fields || {};
    const v = (f.fixVersions || []).find(function (x) { return String(x.id || x.name) === String(d.groupKey); });
    if (!v) continue;
    const openLlrs = (f.issuelinks || []).filter(function (l) { return l.type && l.type.id === LINK_TYPE_ID && l.outwardIssue; }).map(function (l) { return l.outwardIssue; }).filter(function (l) { const st = l.fields && l.fields.status; return !(st && st.statusCategory && st.statusCategory.key === 'done'); });
    if (!openLlrs.length) continue;
    vName = v.name; vDate = v.releaseDate || vDate; project = it.key.split('-')[0];
    open += openLlrs.length;
    const sub = openLlrs.map(function (l) { const st = l.fields && l.fields.status; return '      ◦ LLR: ' + link(l.key) + ' → *' + esc(st ? st.name : 'unknown') + '*'; });
    lines.push('• ' + link(it.key) + ' – ' + esc(f.summary) + ' → *' + esc(f.status ? f.status.name : '') + '*\n' + sub.join('\n'));
  }
  if (!open) continue;
  const head = ':rotating_light: *Released with open localization work* – Version *' + esc(vName) + '* (' + esc(project) + ')' + (vDate ? ', released on *' + vDate + '*' : '');
  const sum = '*' + open + ' linked localization request' + (open > 1 ? 's are' : ' is') + ' not Done yet.*';
  out.push({ json: { text: head + '\n' + sum + '\n' + lines.join('\n') } });
}
return out;
